class Solution {
public:
    string alphabetBoardPath(string target) {
        string ans="";
        map<char,pair<int,int>> mp;
        for(int i=0;i<26;i++)
            mp[i+'a']={i/5,i%5};
        int dx=0,dy=0;
        target='a'+target;
        int n=target.size();
        for(int i=1;i<n;i++)
        {
            dx=mp[target[i]].first-mp[target[i-1]].first;
            dy=mp[target[i]].second-mp[target[i-1]].second;
            if(dx<0)
                ans+=string(-dx,'U');
            if(dy<0)
                ans+=string(-dy,'L');
            if(dx>0)
                ans+=string(dx,'D');
            if(dy>0)
                ans+=string(dy,'R');
            ans+='!';
        }
        return ans;
    }
};

class Solution(object):
    def alphabetBoardPath(self, target):
        """
        :type target: str
        :rtype: str
        """
        ans = ""
        cur_pos = (0, 0)
        for c in target:
            diff = ord(c) - ord('a')
            new_pos = (diff // 5, diff % 5)
            if new_pos[0] < cur_pos[0]:
                ans += "U" * (cur_pos[0] - new_pos[0])
            if new_pos[1] < cur_pos[1]:
                ans += "L" * (cur_pos[1] - new_pos[1])
            if new_pos[0] > cur_pos[0]:
                ans += "D" * (new_pos[0] - cur_pos[0])
            if new_pos[1] > cur_pos[1]:
                ans += "R" * (new_pos[1] - cur_pos[1])
            ans += "!"
            cur_pos = new_pos
        return ans
